import './styles.css';
import { supabase, isSupabaseConfigured } from './supabase.js';
import * as pdfjsLib from 'pdfjs-dist';
import pdfWorker from 'pdfjs-dist/build/pdf.worker.min.mjs?url';

pdfjsLib.GlobalWorkerOptions.workerSrc = pdfWorker;

const obligations = [
  ['Impuestos','IVA'], ['Impuestos','Ingresos Brutos'], ['Impuestos','ATM'],
  ['Servicios','EDEMSA local'], ['Servicios','EDEMSA casa'], ['Servicios','Ecogas'],
  ['Comunicaciones','Celular'], ['Comunicaciones','Internet local - Punto Net'], ['Comunicaciones','Movistar Fibra casa'],
  ['Software','Sistema Flexxus'], ['Educación','Colegio Giovani'],
  ['Alquileres','Alquiler local'], ['Alquileres','Alquiler casa'],
  ['Municipalidad','Municipalidad casa'], ['Municipalidad','Municipalidad local'], ['Seguros','Seguro local'],
  ['Servicios profesionales','Honorarios contador']
].map((item, i) => ({ id:i+1, category:item[0], name:item[1], active:true, notifications:true }))
 .sort((a,b)=>a.name.localeCompare(b.name,'es',{sensitivity:'base'}));

const today = new Date();
const iso = d => new Date(d.getTime() - d.getTimezoneOffset()*60000).toISOString().slice(0,10);
const add = n => { const d = new Date(today); d.setDate(d.getDate()+n); return iso(d); };
const appState = {
  view:'inicio', filter:'all', search:'', records: JSON.parse(localStorage.getItem('cv_records_v2') || '[]'),
  documents: JSON.parse(localStorage.getItem('cv_documents_v1') || '[]'),
  settings: JSON.parse(localStorage.getItem('cv_settings') || 'null') || {time:'09:00', reminders:['7','3','1','0'], alerts:true}, calendarFilters:['overdue','paid','pending']
};

const money = (n,currency='ARS') => n == null ? 'Sin importe' : new Intl.NumberFormat('es-AR',{style:'currency',currency:currency||'ARS',maximumFractionDigits:0}).format(n);
const dateFmt = s => new Intl.DateTimeFormat('es-AR',{day:'2-digit',month:'short'}).format(new Date(`${s}T12:00:00`));
const statusMap = {paid:['Pagado','ok'], overdue:['Vencido','danger'], soon:['Próximo','warn'], pending:['Pendiente','neutral'], review:['Requiere revisión','review'], 'due-today':['Vence hoy','today']};
const icon = (name) => ({home:'⌂', list:'≡', calendar:'▦', file:'▱', pay:'✓', report:'↗', settings:'⚙'}[name] || '•');

function nav(){
  const items=[['inicio','home','Inicio'],['documentos','file','Cargar impuesto'],['vencimientos','list','Vencimientos'],['calendario','calendar','Calendario'],['pagos','pay','Pagos'],['reportes','report','Reportes'],['configuracion','settings','Configuración']];
  return `<aside class="sidebar"><div class="brand"><span class="brandmark">✓</span><div><b>Control</b><small>de vencimientos</small></div></div><nav>${items.map(([v,i,l])=>`<button data-view="${v}" class="${appState.view===v?'active':''}"><span>${icon(i)}</span>${l}</button>`).join('')}</nav><div class="user"><div class="avatar">FP</div><div><b>Administrador</b><small>Cuenta principal</small></div></div></aside>`;
}

function top(title, subtitle='Todo bajo control, sin planillas.'){
  const notificationCount=appState.records.filter(record=>record.status!=='paid').length;
  return `<header class="top"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="top-actions"><button class="notification-button" id="notifyBtn" type="button" aria-label="Notificaciones: ${notificationCount}"><span class="notification-bell" aria-hidden="true">♧</span><span class="notification-label">Notificaciones</span><strong class="notification-count">${notificationCount}</strong></button></div></header>`;
}

function stat(label,value,meta,kind){return `<article class="stat ${kind}"><div class="stat-icon">${kind==='money'?'$':kind==='danger'?'!':kind==='warn'?'◷':kind==='ok'?'✓':'?'}</div><div><span>${label}</span><strong>${value}</strong><small>${meta}</small></div></article>`}
stat=function(label,value,meta,kind,filter=''){return `<button type="button" class="stat ${kind}" ${filter?`data-stat-filter="${filter}"`:''}><div class="stat-icon">${kind==='money'?'$':kind==='danger'?'!':kind==='warn'?'◷':kind==='ok'?'✓':'?'}</div><div><span>${label}</span><strong>${value}</strong><small>${meta}</small></div></button>`};
function statusSelector(r){
 if(!['paid','pending'].includes(r.status)){const [label,kind]=statusMap[r.status]||statusMap.pending;return `<div class="status-selector"><span class="badge ${kind}"><i></i>${label}</span><button class="status-option paid" data-set-status="paid" data-record-id="${r.id}" type="button"><i></i>Pagado</button></div>`}
 return `<div class="status-selector" role="group" aria-label="Estado del vencimiento"><button class="status-option pending ${r.status==='pending'?'active':''}" data-set-status="pending" data-record-id="${r.id}" type="button"><i></i>Pendiente</button><button class="status-option paid ${r.status==='paid'?'active':''}" data-set-status="paid" data-record-id="${r.id}" type="button"><i></i>Pagado</button></div>`
}
function row(r){const [,kind]=statusMap[r.status]||statusMap.pending;const daysOverdue=r.status!=='paid'&&r.due?Math.max(0,Math.floor((new Date(iso(today)+'T12:00:00')-new Date(r.due+'T12:00:00'))/86400000)):0;const dueLabel=r.status==='paid'?'<span class="paid-date-label">✓ Pagado</span>':daysOverdue?`<span class="overdue-days">${daysOverdue} ${daysOverdue===1?'día':'días'} vencido</span>`:'';return `<tr data-id="${r.id}"><td><div class="ob"><span class="catdot ${kind}"></span><div><b>${r.obligation}</b><small>${r.category}</small></div></div></td><td>${r.period}${r.installment?`<small class="installment-label">Cuota ${r.installment}</small>`:''}</td><td><div class="due-with-delay ${r.status==='paid'?'is-paid':''}"><b>${dateFmt(r.due)}</b>${dueLabel}</div></td><td class="amount">${money(r.amount,r.currency)}</td><td>${statusSelector(r)}${r.status==='paid'&&r.paymentMethod?`<small class="payment-method">${safe(r.paymentMethod)}</small>`:''}</td><td class="row-actions"><button class="outline edit-row-button" data-edit-record="${r.id}" type="button">Editar</button><button class="outline delete-row-button" data-delete-record="${r.id}" type="button">Eliminar</button></td></tr>`}
function obligationRow(o){return `<tr data-obligation="${o.id}"><td><div class="ob"><span class="catdot review"></span><div><b>${o.name}</b><small>${o.category}</small></div></div></td><td class="muted-cell">—</td><td class="muted-cell">Sin fecha</td><td class="muted-cell">Sin importe</td><td><span class="badge review"><i></i>Sin información</span></td><td class="row-actions"><button class="row-upload" data-upload-obligation="${o.name}">＋ Cargar</button><button class="outline delete-row-button" data-delete-empty-obligation="${o.id}" type="button">Eliminar</button></td></tr>`}

function dashboard(){
 const unpaidRecords=appState.records.filter(r=>r.status!=='paid'&&r.amount);const pending=unpaidRecords.filter(r=>(r.currency||'ARS')==='ARS').reduce((a,r)=>a+Number(r.amount),0);const pendingUsd=unpaidRecords.filter(r=>r.currency==='USD').reduce((a,r)=>a+Number(r.amount),0);
 const overdue=appState.records.filter(r=>r.status==='overdue'); const soon=appState.records.filter(r=>['soon','due-today'].includes(r.status)); const paid=appState.records.filter(r=>r.status==='paid'); const review=appState.records.filter(r=>r.status==='review');
 const dueToday=appState.records.filter(r=>r.due===iso(today)&&r.status!=='paid');
 const greeting=`BUEN DÍA 👋${currentUser?.name?` ${safe(currentUser.name)}`:''}`;
 if(!obligations.length&&!appState.records.length)return `${top(greeting,'Tu agenda está lista para empezar.')}<section class="panel onboarding-empty"><span class="onboarding-icon">＋</span><span class="eyebrow">PRIMEROS PASOS</span><h2>Empezá a cargar tus impuestos y facturas</h2><p>Agregá las obligaciones que quieras controlar —impuestos, servicios, alquileres o suscripciones— y después registrá sus vencimientos.</p><div><button class="primary" data-view="configuracion">Agregar mi primer impuesto</button></div><small>Tu agenda empieza en blanco y es privada para tu usuario.</small></section>`;
 return `${top(greeting)}<section class="hero-alert"><div class="alert-bell">♧</div><div><span>HOY · RECORDATORIO ACTIVO</span><h2>${dueToday.length ? `${dueToday[0].obligation} vence hoy` : 'No hay vencimientos para hoy'}</h2><p>${dueToday.length ? `${dueToday[0].period} · ${money(dueToday[0].amount)} · Aún no figura como pagado.` : 'Cargá una factura para comenzar.'}</p></div>${dueToday.length?`<button data-view="vencimientos">Ver vencimiento <b>→</b></button>`:''}</section>
 <section class="stats">${stat('Total pendiente',money(pending,'ARS'),'Obligaciones en pesos','money','unpaid')}${stat('Pendiente en USD',money(pendingUsd,'USD'),'Obligaciones en dólares','money','unpaid')}${stat('Vencidos',overdue.length,overdue.length?'Requieren atención':'Sin vencidos','danger','overdue')}${stat('Próximos',soon.length,'En los próximos 5 días','warn','soon')}${stat('Pagados',paid.length,'Este mes','ok','paid')}${stat('Sin información',review.length,'Para revisar','review','review')}</section>
 <section class="two-col"><div class="panel"><div class="panel-head"><div><span class="eyebrow">PRIORIDAD</span><h2>Próximos vencimientos</h2></div><button class="link" data-view="vencimientos">Ver todos →</button></div><div class="table-wrap"><table><thead><tr><th>Obligación</th><th>Período</th><th>Vence</th><th>Importe</th><th>Estado</th><th></th></tr></thead><tbody>${appState.records.length?appState.records.filter(r=>r.status!=='paid').slice(0,5).map(row).join(''):'<tr><td colspan="6" class="empty">Todavía no cargaste vencimientos.</td></tr>'}</tbody></table></div></div>
 <div class="side-stack"><div class="panel upload-card"><span class="upload-icon">⇧</span><h2>¿Tenés un documento?</h2><p>Subí una factura o comprobante. Nosotros hacemos el resto.</p><button class="primary full" id="uploadCard">＋ Cargar un impuesto</button><small>PDF, JPG o PNG · Máx. 15 MB</small></div><div class="panel mini"><div class="panel-head"><h3>Últimos pagos</h3><button class="link" data-view="pagos">Ver todos</button></div>${paid.length?paid.map(r=>`<div class="payment"><span>✓</span><div><b>${r.obligation}</b><small>${r.period} · ${dateFmt(r.paid)}</small></div><strong>${money(r.amount)}</strong></div>`).join(''):'<p class="empty">Todavía no hay pagos.</p>'}</div></div></section>`;
}

function recordsView(){
 let records=appState.records.filter(r=>appState.filter==='all'||(appState.filter==='unpaid'?r.status!=='paid':appState.filter==='soon'?['soon','due-today'].includes(r.status):r.status===appState.filter));
 records.sort((a,b)=>(a.due||'9999-12-31').localeCompare(b.due||'9999-12-31'));
 if(appState.search){const q=appState.search.toLowerCase();records=records.filter(r=>`${r.obligation} ${r.category} ${r.period} ${r.amount}`.toLowerCase().includes(q));}
 let emptyObligations=[];
 if(appState.filter==='all'||appState.filter==='review'){
   const q=appState.search.toLowerCase();
   emptyObligations=obligations.filter(o=>o.active!==false&&!appState.records.some(r=>r.obligation===o.name)&&(!q||`${o.name} ${o.category}`.toLowerCase().includes(q)));
 }
 const rows=[...records.map(row),...emptyObligations.map(obligationRow)].join('');
 return `${top('Vencimientos',`Tus ${obligations.length} obligaciones aparecen siempre, aunque todavía no tengan una factura cargada.`)}<div class="toolbar"><label class="search">⌕<input id="search" placeholder="Buscar obligación, período o importe" value="${appState.search}"></label><button class="outline">☷ Filtros</button></div><div class="tabs">${[['all','Todos'],['paid','Pagados'],['pending','Pendientes'],['soon','Próximos'],['overdue','Vencidos'],['review','Sin información']].map(([k,l])=>`<button class="${appState.filter===k?'active':''}" data-filter="${k}">${l}</button>`).join('')}</div><div class="panel records"><div class="records-head"><b>${records.length+emptyObligations.length} ítems</b><span>Los ítems sin factura no generan alertas.</span></div><div class="table-wrap"><table><thead><tr><th>Obligación</th><th>Período</th><th>Vencimiento</th><th>Importe</th><th>Estado</th><th></th></tr></thead><tbody>${rows||`<tr><td colspan="6" class="empty">No encontramos resultados.</td></tr>`}</tbody></table></div></div>`;
}

function settingsView(){const s=appState.settings;const granted='Notification' in window&&Notification.permission==='granted';return `${top('Configuración','Personalizá alertas y preferencias de la aplicación.')}<div class="settings-grid"><section class="panel settings-card"><div class="setting-title"><span class="setting-icon">♧</span><div><h2>Alertas de vencimiento</h2><p>Recibí notificaciones en este teléfono aunque la aplicación esté cerrada.</p></div><label class="switch"><input id="alertsToggle" type="checkbox" ${s.alerts?'checked':''}><span></span></label></div><div class="setting-row"><div><b>Alerta el día del vencimiento</b><small>Solo si no existe un pago confirmado</small></div><strong class="required">Obligatoria</strong></div><div class="setting-row"><div><b>Horario de notificación</b><small>Zona horaria: Buenos Aires (GMT-3)</small></div><input id="alertTime" type="time" value="${s.time}"></div><div class="setting-row vertical"><div><b>Recordatorios anticipados</b><small>Elegí cuándo querés recibir avisos adicionales</small></div><div class="checks">${[['7','7 días antes'],['3','3 días antes'],['1','1 día antes'],['0','El mismo día']].map(([v,l])=>`<label><input type="checkbox" data-reminder="${v}" ${s.reminders.includes(v)?'checked':''}> ${l}</label>`).join('')}</div></div><button class="primary" id="enablePush">Activar notificaciones en este dispositivo</button><p class="hint" id="pushStatus">${granted?'✓ Notificaciones autorizadas en este navegador.':'Se solicitará permiso del sistema.'}</p></section><section class="panel settings-card"><h2>Obligaciones</h2><p>Las ${obligations.length} obligaciones iniciales están preparadas, sin importes ni vencimientos ficticios.</p><div class="obligation-list">${obligations.map(o=>`<div><span>${o.name}</span><small>${o.category}</small></div>`).join('')}</div></section></div>`}

function placeholder(){const names={calendario:'Calendario',documentos:'Documentos',pagos:'Pagos',reportes:'Reportes'};return `${top(names[appState.view]||'Control de Vencimientos')}<section class="panel placeholder"><span>${appState.view==='calendario'?'□':appState.view==='pagos'?'✓':'▱'}</span><h2>${names[appState.view]}</h2><p>Esta sección está preparada para conectar los datos reales de tus documentos.</p><button class="primary" id="uploadPlaceholder">＋ Cargar un impuesto</button></section>`}

function mobileNav(){return `<div class="mobile-nav">${[['inicio','⌂','Inicio'],['vencimientos','≡','Vence.'],['upload','＋',''],['calendario','▦','Calendario'],['configuracion','⚙','Ajustes']].map(([v,i,l])=>v==='upload'?`<button class="upload-fab" id="mobileUpload">${i}</button>`:`<button data-view="${v}" class="${appState.view===v?'active':''}"><span>${i}</span>${l}</button>`).join('')}</div>`}
function render(){let content=appState.view==='inicio'?dashboard():appState.view==='vencimientos'?recordsView():appState.view==='configuracion'?settingsView():placeholder();document.querySelector('#app').innerHTML=`${nav()}<main>${content}</main>${mobileNav()}<input hidden id="fileInput" type="file" accept="application/pdf,image/jpeg,image/png" capture="environment"><div id="modalRoot"></div><div id="toast"></div>`;bind();}

function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3200)}
function openUpload(){document.querySelector('#fileInput').click()}
function closeModal(){document.querySelector('#modalRoot').innerHTML=''}
function openLoadMenu(target=''){
 document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal choice-modal"><button class="modal-close" data-close>×</button><span class="modal-kicker">NUEVO REGISTRO</span><h2>${target?target:'Cargar información'}</h2><p>Elegí cómo querés incorporar los datos.</p><div class="choice-grid"><button id="chooseFile"><span>⇧</span><b>Subir documento</b><small>PDF, JPG o PNG</small></button><button id="chooseManual"><span>✎</span><b>Carga manual</b><small>Completá los datos</small></button></div></section></div>`;
 document.querySelector('[data-close]').onclick=closeModal;
 document.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()};
 document.querySelector('#chooseFile').onclick=()=>{if(target)localStorage.setItem('cv_upload_target',target);closeModal();openUpload()};
 document.querySelector('#chooseManual').onclick=()=>openManualForm(target);
}
function statusFor(dueValue){const due=new Date(`${dueValue}T12:00:00`);const diff=Math.ceil((due-today)/86400000);return diff<0?'overdue':diff===0?'due-today':diff<=5?'soon':'pending'}
function shiftMonth(dateValue,months=1){
 if(!dateValue)return'';const [year,month,day]=dateValue.split('-').map(Number);const target=new Date(year,month-1+months,1,12);const lastDay=new Date(target.getFullYear(),target.getMonth()+1,0).getDate();target.setDate(Math.min(day,lastDay));return iso(target)
}
function periodFor(dateValue){const [year,month]=dateValue.split('-');return `${month}/${year}`}
function ensureMonthlyRecords(){
 let changed=false;const currentMonth=iso(today).slice(0,7);
 obligations.filter(item=>item.active!==false&&item.recurring===true).forEach(obligation=>{
  let records=appState.records.filter(record=>record.obligation===obligation.name&&record.due).sort((a,b)=>a.due.localeCompare(b.due));
  if(!records.length)return;
  while(records.at(-1).due.slice(0,7)<currentMonth){
   const sourceMonth=records.at(-1).due.slice(0,7);const sourceGroup=records.filter(record=>record.due.slice(0,7)===sourceMonth);const nextMonth=shiftMonth(`${sourceMonth}-01`).slice(0,7);
   if(appState.records.some(record=>record.obligation===obligation.name&&record.due?.slice(0,7)===nextMonth))break;
   const copies=sourceGroup.map(source=>{const due=shiftMonth(source.due);return {...source,id:newUuid(),period:periodFor(due),due,issued:source.issued?shiftMonth(source.issued):'',status:statusFor(due),invoice:'',paid:'',paymentMethod:'',created:iso(new Date()),recurringGenerated:true}});
   appState.records.push(...copies);records.push(...copies);changed=true;
  }
 });
 if(changed)cacheCloudData();return changed
}
function saveInstallments(data){
 const obligation=obligations.find(o=>o.name===data.obligation);if(obligation)obligation.recurring=Boolean(data.recurring);const total=Number(data.totalAmount||data.amount);const split=Boolean(data.due2);const installmentAmount=split?total/2:total;const base={obligation:data.obligation,category:obligation?.category||'',period:data.period,issued:data.issued,currency:data.currency,invoice:data.invoice,notes:data.notes,created:iso(new Date()),totalAmount:total};
 appState.records.push({id:Date.now(),...base,due:data.due,amount:installmentAmount,status:statusFor(data.due),installment:split?'1/2':''});
 if(split)appState.records.push({id:Date.now()+1,...base,due:data.due2,amount:installmentAmount,status:statusFor(data.due2),installment:'2/2'});
 localStorage.setItem('cv_records_v2',JSON.stringify(appState.records));closeModal();appState.view='vencimientos';render();toast(split?'Se guardaron los 2 vencimientos':'Vencimiento guardado correctamente');
}
function openManualForm(target=''){
 const options=obligations.filter(o=>o.active!==false||o.name===target).map(o=>`<option value="${o.name}" ${o.name===target?'selected':''}>${o.name}</option>`).join('');
 document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal form-modal"><button class="modal-close" data-close>×</button><span class="modal-kicker">CARGA MANUAL</span><h2>Nuevo vencimiento</h2><p>Para EDEMSA podés cargar las dos fechas. El importe total se divide automáticamente en dos cuotas.</p><form id="manualForm"><label class="wide">Obligación *<select name="obligation" required><option value="">Seleccionar…</option>${options}</select></label><label>Período *<input name="period" placeholder="Ej. 10/2026" required></label><label>Moneda<select name="currency"><option value="ARS">ARS - Pesos</option><option value="USD">USD - Dólares</option></select></label><label>Fecha de emisión<input name="issued" type="date"></label><label>Primer vencimiento *<input name="due" type="date" required></label><label>Segundo vencimiento<input name="due2" type="date"></label><label>Importe total de la factura *<input name="totalAmount" type="number" min="0" step="0.01" placeholder="0,00" required></label><label class="installment-preview">Importe por vencimiento<input id="manualInstallment" readonly placeholder="Se calcula automáticamente"></label><label>Número de factura<input name="invoice" placeholder="Ej. 0001-00001234"></label><label class="wide">Observaciones<textarea name="notes" rows="3" placeholder="Información adicional"></textarea></label><div class="form-actions wide"><button type="button" class="outline" data-close>Cancelar</button><button type="submit" class="primary">Guardar vencimiento(s)</button></div></form></section></div>`;
 const manualFormElement=document.querySelector('#manualForm');if(manualFormElement){const documentOption=document.createElement('div');documentOption.className='wide manual-document-option';documentOption.innerHTML='<span class="upload-icon">⇧</span><div><b>¿Tenés el comprobante?</b><small>Subí un PDF, JPG o PNG y revisá los datos detectados.</small></div><button class="outline" type="button" id="manualUploadDocument">Subir documento</button>';manualFormElement.before(documentOption);const createOption=document.createElement('section');createOption.className='manual-create-obligation';createOption.innerHTML='<div class="form-divider"><span>o agregá uno nuevo</span></div><form id="manualObligationForm"><label>Nombre<input name="name" required placeholder="Ej. Monotributo"></label><label>Categoría<select name="category"><option>Impuestos</option><option>Servicios</option><option>Comunicaciones</option><option>Alquileres</option><option>Seguros</option><option>Educación</option><option>Software</option><option>Otro</option></select></label><button class="primary" type="submit">＋ Agregar y continuar</button></form>';documentOption.before(createOption);document.querySelector('#manualObligationForm').onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));const name=data.name.trim();if(obligations.some(item=>normalizeText(item.name)===normalizeText(name))){toast('Ese impuesto ya está en tu agenda');return}const obligation={id:newUuid(),name,category:data.category,active:true,notifications:true,custom:true,recurring:false};obligations.push(obligation);obligations.sort((a,b)=>a.name.localeCompare(b.name,'es'));const select=manualFormElement.querySelector('[name="obligation"]');const option=document.createElement('option');option.value=name;option.textContent=name;option.selected=true;select.append(option);persistUserData();event.currentTarget.reset();toast('Impuesto agregado y seleccionado')};document.querySelector('#manualUploadDocument').onclick=()=>{const selected=manualFormElement.querySelector('[name="obligation"]')?.value||target;if(selected)localStorage.setItem('cv_upload_target',selected);closeModal();document.querySelector('#fileInput')?.click()}}
 document.querySelector('#manualObligationForm')?.addEventListener('submit',event=>{const addedName=event.currentTarget.elements.name.value.trim();setTimeout(()=>{const select=manualFormElement?.querySelector('[name="obligation"]');if(!select||!obligations.some(item=>item.name===addedName))return;select.innerHTML='<option value="">Seleccionar…</option>'+obligations.filter(item=>item.active!==false).map(item=>`<option value="${safe(item.name)}">${safe(item.name)}</option>`).join('');select.value=addedName;select.dispatchEvent(new Event('change',{bubbles:true}));select.closest('label')?.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>select.focus(),350);toast('Impuesto agregado y seleccionado. Continuá la carga abajo.')},0)},true);
 const notesField=document.querySelector('#manualForm textarea[name="notes"]')?.closest('label');if(notesField){const recurring=document.createElement('label');recurring.className='wide recurring-option';recurring.innerHTML=`<input name="recurring" type="checkbox" ${obligations.find(item=>item.name===(target||document.querySelector('#manualForm select[name="obligation"]')?.value))?.recurring?'checked':''}><span><b>Repetir todos los meses</b><small>Se creará automáticamente el vencimiento de cada mes con estos datos.</small></span>`;notesField.before(recurring)}
 document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);document.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()};
 const form=document.querySelector('#manualForm');const update=()=>{const total=Number(form.totalAmount.value);document.querySelector('#manualInstallment').value=total?(form.due2.value?`${(total/2).toFixed(2)} cada uno`:total.toFixed(2)):''};form.totalAmount.oninput=update;form.due2.onchange=update;
 form.onsubmit=e=>{e.preventDefault();saveInstallments(Object.fromEntries(new FormData(e.currentTarget)))};
}
const normalizeText=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const pdfDate=value=>{const m=value?.match(/(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})/);if(!m)return'';return `${m[3].length===2?'20'+m[3]:m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`};
const pdfAmount=value=>{if(!value)return'';let s=value.replace(/[^\d.,]/g,'');if(s.includes(',')&&s.includes('.'))s=s.lastIndexOf(',')>s.lastIndexOf('.')?s.replaceAll('.','').replace(',','.'):s.replaceAll(',','');else if(s.includes(','))s=s.replace(',','.');return Number(s)||''};
function obligationFromPdf(text,target){if(target)return target;const s=normalizeText(text);const aliases=[['Ingresos Brutos',['ingresos brutos','iibb']],['IVA',['impuesto al valor agregado','iva']],['ATM',['administracion tributaria mendoza']],['EDEMSA local',['edemsa']],['Ecogas',['ecogas']],['Celular',['telefonia movil','celular']],['Internet local - Punto Net',['punto net','puntonet']],['Movistar Fibra casa',['movistar fibra']],['Sistema Flexxus',['flexxus']],['Colegio Giovani',['giovani']],['Municipalidad casa',['municipalidad']],['Seguro local',['seguro','poliza']],['Honorarios contador',['honorarios']]];return aliases.find(([,words])=>words.some(word=>s.includes(word)))?.[0]||''}
async function extractPdf(file){const pdf=await pdfjsLib.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;const pages=[];for(let n=1;n<=pdf.numPages;n++){const page=await pdf.getPage(n);const content=await page.getTextContent();pages.push(content.items.map(item=>item.str).join(' '))}return pages.join('\n')}
function pdfDraft(text,target,fileName){
 const s=text.replace(/\s+/g,' ');const dates=[...s.matchAll(/\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4}/g)].map(x=>x[0]);const issued=s.match(/emisi[oó]n\s*[:\-]?\s*(\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4})/i)?.[1]||dates[0];
 const labeled=[...s.matchAll(/(?:primer|segundo|1(?:er|ro|°)?|2(?:do|°)?)?\s*vencimiento\s*[:\-]?\s*(\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4})/gi)].map(x=>x[1]);
 const obligation=obligationFromPdf(s,target);const isEdemsa=obligation.startsWith('EDEMSA');const candidates=labeled.length?labeled:dates.filter(date=>date!==issued);const due=pdfDate(isEdemsa&&candidates.length>1?candidates.at(-2):candidates.at(-1)||dates.at(-1));const due2=isEdemsa&&candidates.length>1?pdfDate(candidates.at(-1)):'';
 const total=pdfAmount(s.match(/(?:total\s+(?:a\s+)?pagar|importe\s+total|total)\s*[:$ ]+([\d.,]+)/i)?.[1]);
 return {obligation,period:s.match(/per[ií]odo\s*[:\-]?\s*(\d{1,2}[\/-]\d{4})/i)?.[1]?.replace('-','/')||(due?`${due.slice(5,7)}/${due.slice(0,4)}`:''),due,due2,issued:pdfDate(issued),totalAmount:total,amount:due2&&total?total/2:total,currency:/\bUSD\b|U\$S|D[OÓ]LAR/i.test(s)?'USD':'ARS',invoice:s.match(/(?:factura|comprobante|n[º°ro.]*)\s*[:\-]?\s*([A-Z]?\s*\d{1,5}[- ]\d{4,12})/i)?.[1]?.replace(/\s/g,'')||'',notes:`Importado desde ${fileName}`}
}
function openPdfReview(d){
 const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;');const options=obligations.map(o=>`<option value="${o.name}" ${o.name===d.obligation?'selected':''}>${o.name}</option>`).join('');
 document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal form-modal"><button class="modal-close" data-close>×</button><span class="modal-kicker">DATOS EXTRAÍDOS DEL PDF</span><h2>Revisar vencimiento${d.due2?'s':''}</h2><p>${d.due2?'Detectamos dos vencimientos. Corroborá las fechas, el total y el valor de cada cuota.':'Revisá los datos detectados y completá los que falten.'}</p><form id="manualForm"><label class="wide">Obligación *<select name="obligation" required><option value="">Seleccionar…</option>${options}</select></label><label>Período *<input name="period" value="${esc(d.period)}" required></label><label>Moneda<select name="currency"><option value="ARS" ${d.currency==='ARS'?'selected':''}>ARS - Pesos</option><option value="USD" ${d.currency==='USD'?'selected':''}>USD - Dólares</option></select></label><label>Fecha de emisión<input name="issued" type="date" value="${esc(d.issued)}"></label><label>Primer vencimiento *<input name="due" type="date" value="${esc(d.due)}" required></label><label>Segundo vencimiento<input name="due2" type="date" value="${esc(d.due2)}"></label><label>Importe total de la factura *<input name="totalAmount" type="number" min="0" step="0.01" value="${esc(d.totalAmount)}" required></label><label>Importe por vencimiento<input id="pdfInstallment" readonly value="${esc(d.amount)}"></label><label>Número de factura<input name="invoice" value="${esc(d.invoice)}"></label><label class="wide">Observaciones<textarea name="notes" rows="3">${esc(d.notes)}</textarea></label><div class="form-actions wide"><button type="button" class="outline" data-close>Cancelar</button><button type="submit" class="primary">Guardar vencimiento(s)</button></div></form></section></div>`;
 document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);const form=document.querySelector('#manualForm');const update=()=>{const total=Number(form.totalAmount.value);document.querySelector('#pdfInstallment').value=total?(form.due2.value?`${(total/2).toFixed(2)}`:total.toFixed(2)):''};form.totalAmount.oninput=update;form.due2.onchange=update;form.onsubmit=e=>{e.preventDefault();saveInstallments(Object.fromEntries(new FormData(e.currentTarget)))};
}
async function handleDocument(file){const target=localStorage.getItem('cv_upload_target')||'';localStorage.removeItem('cv_upload_target');if(file.size>15*1024*1024){toast('El archivo supera el máximo de 15 MB.');return}if(file.type!=='application/pdf'){toast('La extracción automática está disponible para PDF.');openManualForm(target);return}toast(`Analizando ${file.name}…`);try{const text=await extractPdf(file);if(!text.trim())throw new Error('No se detectó texto');openPdfReview(pdfDraft(text,target,file.name));toast('Datos visibles. Revisalos y guardá el vencimiento.')}catch(error){console.error(error);toast('El PDF es una imagen escaneada. Completá los datos manualmente.');openManualForm(target)}}
function bind(){
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{appState.view=b.dataset.view;render()});
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{appState.filter=b.dataset.filter;render()});
 ['uploadTop','uploadCard','uploadPlaceholder','mobileUpload'].forEach(id=>{const e=document.getElementById(id);if(e)e.onclick=()=>openLoadMenu()});
 const input=document.querySelector('#fileInput');input.onchange=async()=>{const file=input.files[0];if(!file)return;await handleDocument(file);input.value=''};
 document.querySelectorAll('[data-upload-obligation]').forEach(b=>b.onclick=()=>openLoadMenu(b.dataset.uploadObligation));
 const search=document.querySelector('#search');if(search)search.oninput=e=>{appState.search=e.target.value;setTimeout(render,180)};
 const toggle=document.querySelector('#alertsToggle');if(toggle)toggle.onchange=e=>saveSettings({...appState.settings,alerts:e.target.checked});
 const time=document.querySelector('#alertTime');if(time)time.onchange=e=>saveSettings({...appState.settings,time:e.target.value});
 document.querySelectorAll('[data-reminder]').forEach(c=>c.onchange=()=>saveSettings({...appState.settings,reminders:[...document.querySelectorAll('[data-reminder]:checked')].map(x=>x.dataset.reminder)}));
 const enable=document.querySelector('#enablePush');if(enable)enable.onclick=async()=>{if(!('Notification'in window)){toast('Este navegador no admite notificaciones.');return}const p=await Notification.requestPermission();document.querySelector('#pushStatus').textContent=p==='granted'?'✓ Notificaciones autorizadas. El backend podrá enviar las alertas.':'No se otorgó permiso para notificaciones.';if(p==='granted')new Notification('Alertas activadas',{body:`Te avisaremos a las ${appState.settings.time} cuando un vencimiento siga pendiente.`,icon:'/icon.svg'})};
}
