let currentUser=null;
const userKey=(suffix,user=currentUser)=>`impueston_${user?.id}_${suffix}`;
const safe=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const bytesToHex=bytes=>[...bytes].map(b=>b.toString(16).padStart(2,'0')).join('');
async function passwordHash(password,salt){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:120000,hash:'SHA-256'},material,256);return bytesToHex(new Uint8Array(bits))}
function accounts(){return JSON.parse(localStorage.getItem('impueston_accounts_v1')||'[]')}
function saveAccounts(value){localStorage.setItem('impueston_accounts_v1',JSON.stringify(value))}
function persistUserData(){if(!currentUser)return;localStorage.setItem(userKey('records'),JSON.stringify(appState.records));localStorage.setItem(userKey('documents'),JSON.stringify(appState.documents));localStorage.setItem(userKey('settings'),JSON.stringify(appState.settings));localStorage.setItem(userKey('obligations'),JSON.stringify(obligations))}
function loadUserData(user){currentUser=user;appState.records=JSON.parse(localStorage.getItem(userKey('records'))||'[]');appState.documents=JSON.parse(localStorage.getItem(userKey('documents'))||'[]');appState.settings=JSON.parse(localStorage.getItem(userKey('settings'))||'null')||{time:'09:00',reminders:['7','3','1','0'],alerts:true};const saved=JSON.parse(localStorage.getItem(userKey('obligations'))||'[]');obligations.splice(0,obligations.length,...saved.map(o=>({...o,active:o.active!==false})));obligations.sort((a,b)=>a.name.localeCompare(b.name,'es',{sensitivity:'base'}));persistUserData()}
function authScreen(mode='login',message=''){const hasAccounts=accounts().length>0;if(!hasAccounts)mode='register';document.querySelector('#app').innerHTML=`<main class="auth-shell"><section class="auth-brand"><div class="brandmark">✓</div><span>IMPUES<span>TON</span></span><h1>Tu agenda impositiva,<br>simple y personal.</h1><p>Organizá impuestos, servicios, comprobantes y vencimientos desde cualquier pantalla.</p><div class="auth-features"><span>✓ Agenda personalizada</span><span>✓ Datos separados por usuario</span><span>✓ Contraseña protegida</span></div></section><section class="auth-card"><span class="modal-kicker">${mode==='register'?'CREAR CUENTA':'BIENVENIDO'}</span><h2>${mode==='register'?'Empezá a organizarte':'Ingresá a ImpuestON'}</h2><p>${mode==='register'?'Creá tu perfil personal en este dispositivo.':'Accedé a tu agenda y tus documentos.'}</p>${message?`<div class="auth-message">${safe(message)}</div>`:''}<form id="authForm"><label>${mode==='register'?'Tu nombre':'Usuario'}<input name="name" autocomplete="username" required placeholder="${mode==='register'?'Ej. Fernando':'Tu usuario'}"></label>${mode==='register'?'<label>Usuario<input name="username" autocomplete="username" minlength="3" required placeholder="Elegí un usuario"></label>':''}<label>Contraseña<input name="password" type="password" autocomplete="${mode==='register'?'new-password':'current-password'}" minlength="6" required placeholder="Mínimo 6 caracteres"></label><button class="primary full" type="submit">${mode==='register'?'Crear mi cuenta':'Ingresar'}</button></form>${hasAccounts?`<button class="auth-switch" id="switchAuth">${mode==='register'?'Ya tengo una cuenta':'Crear otra cuenta'}</button>`:''}<small>Las cuentas y los datos se guardan localmente en este dispositivo.</small></section></main>`;document.querySelector('#switchAuth')?.addEventListener('click',()=>authScreen(mode==='login'?'register':'login'));document.querySelector('#authForm').onsubmit=e=>submitAuth(e,mode)}
async function submitAuth(event,mode){event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));const username=(data.username||data.name).trim().toLowerCase();const list=accounts();if(mode==='register'){if(list.some(u=>u.username===username)){authScreen('register','Ese usuario ya existe.');return}const salt=crypto.randomUUID();const user={id:crypto.randomUUID(),name:data.name.trim(),username,salt,passwordHash:await passwordHash(data.password,salt),created:new Date().toISOString()};saveAccounts([...list,user]);sessionStorage.setItem('impueston_session',user.id);loadUserData(user,list.length===0);render();return}const user=list.find(u=>u.username===username);if(!user||await passwordHash(data.password,user.salt)!==user.passwordHash){authScreen('login','Usuario o contraseña incorrectos.');return}sessionStorage.setItem('impueston_session',user.id);loadUserData(user);render()}
function logout(){persistUserData();sessionStorage.removeItem('impueston_session');currentUser=null;authScreen('login')}
