 const filters=`<div class="calendar-filters panel"><span>Mostrar:</span>${[['overdue','Vencidos'],['paid','Pagados'],['pending','Pendientes']].map(([value,label])=>`<label class="${value}"><input type="checkbox" data-calendar-filter="${value}" ${selected.includes(value)?'checked':''}><span>${label}</span></label>`).join('')}</div>`;
